#!/usr/bin/env python3
"""modules-evaluated-again.py <folder>: ONE CASE A FOLDER: A MODULE THAT IS EVALUATED AGAIN (deleted from require.cache and asked for anew; imported under another query): under `bun run` the second evaluation is a world of its own: its own variables, functions, classes, symbols, tables.
Whatever the compiler has concluded from "the code of a module runs once" (a variable stored once, the one closure of a function, a constant that is made late, a symbol that is a name, a class object made once) can be told here."""
import os, sys
out = sys.argv[1]; cases = {}
LIB = {
 "a-counter": ('let n = 0;', 'bump: () => ++n, read: () => n', 'a.bump(); a.bump(); AGAIN say(a.read(), b.read(), b.bump(), a.bump(), a.read(), b.read());'),
 "functions": ('function f() { return 1; } const g = () => 2; const h = function () { return 3; };', 'f, g, h', 'AGAIN say(a.f === b.f, a.g === b.g, a.h === b.h, a.f(), b.g()); a.f.mark = 1; say(b.f.mark);'),
 "a-class": ('class K { static count = 0; static made() { return ++K.count; } m() { return "m"; } }', 'K', 'a.K.made(); AGAIN say(a.K === b.K, new a.K() instanceof b.K, a.K.count, b.K.count, b.K.made(), a.K.made(), a.K.prototype === b.K.prototype, a.K.prototype.m === b.K.prototype.m);'),
 "a-table": ('const table = { x: 1, list: [1, 2] }; const frozen = Object.freeze({ y: 1 });', 'table, frozen', 'a.table.x = 9; a.table.list.push(3); AGAIN say(a.table === b.table, b.table.x, b.table.list.length, a.frozen === b.frozen);'),
 "a-map-and-a-set": ('const map = new Map([["k", 1]]); const set = new Set([1]); const re = /x/g; const date = new Date(0);', 'map, set, re, date', 'a.map.set("more", 2); a.set.add(2); a.re.lastIndex = 5; AGAIN say(a.map === b.map, b.map.size, b.set.size, b.re.lastIndex, a.date === b.date);'),
 "a-symbol": ('const k = Symbol("k"); const r = Symbol.for("registered");', 'k, r, stamp: o => { o[k] = 1; return o; }, read: o => o[k]', 'const o = a.stamp({}); AGAIN say(a.k === b.k, a.r === b.r, a.read(o), b.read(o), Object.getOwnPropertySymbols(b.stamp(o)).length);'),
 "closures-over-a-let": ('let state = "fresh"; const set = v => { state = v; }; const get = () => state;', 'set, get', 'a.set("set in the first"); AGAIN say(a.get(), b.get()); b.set("set in the second"); say(a.get(), b.get());'),
 "a-hook": ('let hook = () => "the first hook"; function setHook(f) { hook = f; } function callHook() { return hook(); }', 'setHook, callHook', 'a.setHook(() => "replaced in the first"); AGAIN say(a.callHook(), b.callHook());'),
 "a-constant-computed-at-load": ('globalThis.loads = (globalThis.loads ?? 0) + 1; const stamp = "load " + globalThis.loads; const list = [globalThis.loads]; const made = { at: globalThis.loads };', 'stamp, list, made, read: () => stamp + list[0] + made.at', 'AGAIN say(a.stamp, b.stamp, a.list[0], b.list[0], a.made.at, b.made.at, a.read(), b.read());'),
 "a-private-name": ('class P { #x = 1; static has(o) { return #x in o; } }', 'P', 'AGAIN say(a.P.has(new a.P()), a.P.has(new b.P()), b.P.has(new a.P()), b.P.has(new b.P()));'),
 "a-generator-and-an-async-function": ('let n = 0; function* g() { yield ++n; } async function f() { return ++n; }', 'g, f', 'a.g().next(); AGAIN say(a.g === b.g, b.g().next().value, await b.f(), await a.f());'),
 "a-getter-on-exports": ('let n = 0;', 'get live() { return ++n; }', 'a.live; a.live; AGAIN say(b.live, a.live);'),
 "an-error-class": ('class Mine extends Error { constructor(m) { super(m); this.name = "Mine"; } }', 'Mine, fail: () => { throw new Mine("x"); }', 'AGAIN let e; try { b.fail(); } catch (x) { e = x; } say(e instanceof b.Mine, e instanceof a.Mine, e instanceof Error, e.name);'),
}
SAY = 'const say = (...v) => console.log(...v.map(x => typeof x === "symbol" ? x.toString() : x));\n'
for name, (decl, exports, body) in LIB.items():
    cjs = decl + '\nconsole.log("the library is evaluated");\nmodule.exports = { ' + exports + ' };\n'
    names = [e.split(':')[0].strip() for e in exports.split(', ') if not e.startswith('get ')]
    cases["commonjs-" + name] = {"lib.cjs": cjs, "main.cjs": SAY + '(async () => {\nconst a = require("./lib.cjs");\n' + body.replace('AGAIN', 'delete require.cache[require.resolve("./lib.cjs")]; const b = require("./lib.cjs");') + '\n})();\n'}
    esm = decl + '\nconsole.log("the library is evaluated");\nexport default { ' + exports + ' };\n'
    cases["query-" + name] = {"lib.mjs": esm, "main.mjs": SAY + 'const a = (await import("./lib.mjs")).default;\n' + body.replace('AGAIN', 'const b = (await import("./lib.mjs?again")).default;') + '\n'}
    cases["es-deleted-from-the-cache-" + name] = {"lib.mjs": esm, "main.mjs": SAY + 'const a = (await import("./lib.mjs")).default;\n' + body.replace('AGAIN', 'delete require.cache[require.resolve("./lib.mjs")]; const b = (await import("./lib.mjs")).default;') + '\n'}
TS = '''let n: number = 0; export function bump(): number { return ++n; } export class K { static count: number = 0; v: number = 1; } export const table: { x: number } = { x: 1 }; export const k: symbol = Symbol("k"); export interface Row { id: number; name: string } export function row(id: number): Row { return { id, name: "r" + id }; } export function name(r: Row): string { return r.name + r.id; }
console.log("the library is evaluated");
'''
cases["typescript-query"] = {"lib.ts": TS, "main.ts": 'const a = await import("./lib.ts"); a.bump(); a.K.count = 5; a.table.x = 9;\nconst b: typeof a = await import("./lib.ts?again" as string);\nconsole.log(a === b, a.bump === b.bump, a.K === b.K, a.table === b.table, a.k === b.k, b.bump(), a.bump(), b.K.count, b.table.x, b.name(a.row(1)), a.name(b.row(2)), new a.K() instanceof b.K);\n'}
cases["typescript-deleted-from-the-cache"] = {"lib.ts": TS, "main.ts": 'const a = await import("./lib.ts"); a.bump(); a.K.count = 5; a.table.x = 9;\ndelete require.cache[require.resolve("./lib.ts")];\nconst b = await import("./lib.ts");\nconsole.log(a === b, a.bump === b.bump, a.K === b.K, a.table === b.table, a.k === b.k, b.bump(), a.bump(), b.K.count, b.table.x, b.name(a.row(1)), a.name(b.row(2)), new a.K() instanceof b.K);\n'}
cases["typescript-required-twice"] = {"lib.ts": TS, "main.ts": 'const a = require("./lib.ts") as typeof import("./lib.ts"); a.bump(); a.K.count = 5; a.table.x = 9;\ndelete require.cache[require.resolve("./lib.ts")];\nconst b = require("./lib.ts") as typeof import("./lib.ts");\nconsole.log(a === b, a.bump === b.bump, a.K === b.K, a.table === b.table, a.k === b.k, b.bump(), a.bump(), b.K.count, b.table.x, b.name(a.row(1)), a.name(b.row(2)), new a.K() instanceof b.K);\n'}
cases["statically-imported-and-evaluated-again"] = {"lib.ts": TS, "main.ts": 'import { bump, K, table, k } from "./lib.ts";\nbump(); K.count = 5; table.x = 9;\ndelete require.cache[require.resolve("./lib.ts")];\nconst b = await import("./lib.ts");\nconsole.log(bump === b.bump, K === b.K, table === b.table, k === b.k, b.bump(), bump(), b.K.count, K.count, b.table.x, table.x);\n'}
cases["thrice"] = {"lib.cjs": 'let n = 0; globalThis.loads = (globalThis.loads ?? 0) + 1; const load = globalThis.loads; module.exports = { bump: () => load + ":" + ++n };\n', "main.cjs": 'const all = []; for (let i = 0; i < 3; i++) { delete require.cache[require.resolve("./lib.cjs")]; all.push(require("./lib.cjs")); }\nconsole.log(all.map(m => m.bump()).join(), all.map(m => m.bump()).join(), new Set(all.map(m => m.bump)).size);\n'}
cases["after-a-throw"] = {"lib.cjs": 'globalThis.tries = (globalThis.tries ?? 0) + 1; let n = 0; exports.bump = () => ++n; exports.early = globalThis.tries; if (globalThis.tries === 1) throw new Error("the first time");\nexports.late = globalThis.tries;\n', "main.cjs": 'let a; try { a = require("./lib.cjs"); } catch (e) { console.log(e.message); }\nconst b = require("./lib.cjs"); console.log(JSON.stringify(b), b.bump(), globalThis.tries);\n'}
# A CommonJS file deleted from require.cache and required again runs as COMPILED code: a second form of the file, its text wrapped in a function that the host calls: what the top of a CommonJS file can see, both times.
TWICE = 'const show = x => { try { return JSON.stringify(x) ?? String(x); } catch (e) { return e.name; } };\nconst key = require.resolve("./lib.cjs");\nfor (let round = 0; round < 3; round++) { let got; try { got = require("./lib.cjs"); } catch (e) { got = "THROWS " + e.name + ": " + e.message; } console.log(round, show(got)); MORE delete require.cache[key]; }\n'
SECOND = {
 "what-the-top-sees": ('module.exports = [this === exports, this === module.exports, typeof arguments, arguments.length, arguments[0] === exports, arguments[1] === require, arguments[2] === module, arguments[3] === __filename, arguments[4] === __dirname, typeof new.target, typeof require, typeof module, __filename.endsWith("lib.cjs"), typeof __dirname];', ''),
 "a-return-at-the-top": ('exports.early = 1; if (exports.early) return; exports.late = 2;', ''),
 "sloppy-at-the-top": ('function f() { return this === undefined ? "strict" : "sloppy"; } undeclared = 5; var o = { a: 1 }; module.exports = [f(), typeof undeclared, delete o.a, (function () { return typeof this; })(), 010];', 'delete globalThis.undeclared;'),
 "use-strict-at-the-top": ('"use strict"; function f() { return this === undefined ? "strict" : "sloppy"; } let r; try { undeclared2 = 5; r = "stored"; } catch (e) { r = e.name; } module.exports = [f(), r];', ''),
 "hoisting": ('module.exports = [typeof late, typeof v, (() => { try { return typeof l; } catch (e) { return e.name; } })(), late()]; function late() { return "late"; } var v = 1; let l = 2;', ''),
 "a-var-is-no-global": ('var mine = 1; function alsoMine() {} module.exports = [typeof globalThis.mine, typeof globalThis.alsoMine, "mine" in globalThis];', ''),
 "the-module-object": ('module.exports = [module.id === __filename || module.id === ".", module.loaded, module.filename === __filename, require.cache[__filename] === module, Array.isArray(module.children), Array.isArray(module.paths), typeof module.parent, typeof module.require, require.main === module, module.exports === exports];', ''),
 "exports-replaced-and-aliased": ('exports.lost = 1; module.exports = { kept: 1 }; exports.alsoLost = 2; module.exports.more = typeof exports.lost;', ''),
 "exports-a-function-or-a-primitive": ('globalThis.turn = (globalThis.turn ?? 0) + 1; module.exports = [function named() {}, 5, "text", null][globalThis.turn % 4];', 'console.log(typeof got, got && got.name);'),
 "throws-every-other-time": ('globalThis.turn2 = (globalThis.turn2 ?? 0) + 1; exports.turn = globalThis.turn2; if (globalThis.turn2 % 2) throw new RangeError("odd " + globalThis.turn2); exports.done = true;', 'console.log(key in require.cache);'),
 "requires-itself": ('exports.before = 1; const me = require("./lib.cjs"); exports.same = me === exports; exports.sawBefore = me.before; exports.sawAfter = me.after; exports.after = 2;', ''),
 "a-cycle": ('exports.name = "lib"; const other = require("./other.cjs"); exports.other = other.name; exports.whatOtherSaw = other.saw;', 'delete require.cache[require.resolve("./other.cjs")];'),
 "a-cycle-of-which-one-stays": ('globalThis.libs = (globalThis.libs ?? 0) + 1; exports.name = "lib " + globalThis.libs; const other = require("./other.cjs"); exports.other = other.name; exports.whatOtherSaw = other.saw;', ''),
 "eval-and-new-function-at-the-top": ('var seen = "a var of the file"; let alsoSeen = "a let of the file"; module.exports = [eval("seen"), eval("alsoSeen"), eval("typeof module"), eval("this === exports"), new Function("return typeof seen")(), (0, eval)("typeof seen"), eval("var made = 1; typeof made"), typeof made];', ''),
 "a-label-a-with-and-a-switch": ('var r = []; outer: for (var i = 0; i < 3; i++) { for (;;) { if (i === 1) continue outer; break; } r.push(i); } switch (r.length) { case 2: r.push("two"); default: r.push("falls"); } module.exports = r;', ''),
 "timers-and-promises-of-the-first": ('globalThis.turn3 = (globalThis.turn3 ?? 0) + 1; const mine = globalThis.turn3; let n = 0; Promise.resolve().then(() => console.log("a job of load", mine, ++n)); setTimeout(() => console.log("a timer of load", mine, ++n), 1); module.exports = mine;', ''),
 "a-class-with-statics-and-blocks": ('globalThis.turn4 = (globalThis.turn4 ?? 0) + 1; class K { static at = globalThis.turn4; static #hidden = "h" + globalThis.turn4; static { K.block = K.#hidden; } static get hidden() { return K.#hidden; } } module.exports = [K.at, K.block, K.hidden, K.name];', ''),
 "json-and-node-modules-beside": ('const data = require("./data.json"); const path = require("node:path"); data.n = (data.n ?? 0) + 1; module.exports = [data.n, path.basename(__filename), require("./data.json") === data];', ''),
 "getters-defined-on-exports": ('let n = 0; Object.defineProperty(exports, "live", { enumerable: true, get() { return ++n; } }); Object.defineProperty(exports, "__esModule", { value: true }); exports.default = "d";', 'console.log(got.live, got.live, got.__esModule);'),
 "function-texts": ('// a comment ahead\nfunction  spaced ( a,b ) { return a+b }\nconst arrow = (x) =>  x * 2;\nclass K { m ( ) { return 1 } static s() {} }\nmodule.exports = [spaced.toString(), arrow.toString(), K.toString(), K.prototype.m.toString(), spaced.name, spaced.length];', ''),
 "places-in-stacks": ('function thrower() {\n  throw new Error("from the library");\n}\nlet place;\ntry { thrower(); } catch (e) { place = e.stack.split("\\n").slice(0, 3).map(l => l.replace(/\\(?[^ ()]*[\\/]/, "").replace(")", "").trim()); }\nmodule.exports = place;', ''),
 "a-shebang-and-no-newline-at-the-end": ('#!/usr/bin/env node\nexports.ok = 1; // the file ends in a comment', ''),
 "imported-by-an-es-module-too": ('globalThis.turn5 = (globalThis.turn5 ?? 0) + 1; exports.turn = globalThis.turn5; exports.named = "n" + globalThis.turn5;', ''),
}
for name, (lib, more) in SECOND.items():
    files = {"lib.cjs": lib + ("" if "no-newline" in name else "\n"), "main.cjs": TWICE.replace("MORE", more)}
    if "cycle" in name: files["other.cjs"] = 'exports.name = "other"; const lib = require("./lib.cjs"); exports.saw = lib.name + ":" + typeof lib.other;\n'
    if "json" in name: files["data.json"] = '{ "a": 1 }\n'
    if name == "imported-by-an-es-module-too":
        del files["main.cjs"]; files["main.mjs"] = 'import lib, { named } from "./lib.cjs";\nimport { createRequire } from "node:module";\nconst require = createRequire(import.meta.url);\nconsole.log(lib.turn, named, require("./lib.cjs") === lib);\ndelete require.cache[require.resolve("./lib.cjs")];\nconst second = require("./lib.cjs");\nconsole.log(second.turn, second.named, lib.turn, named, second === lib);\nconst third = await import("./lib.cjs");\nconsole.log(third.default.turn, third.named, third.default === second, third.default === lib);\n'
    cases["second-form-" + name] = files
# A module that THREW at load and is asked for again runs its COMPILED code again: whatever stands on "the code of a module runs once" shows here.
THREW = 'globalThis.tries = (globalThis.tries ?? 0) + 1; (globalThis.seen ??= []).push({ k: Symbol("k"), f: function f() {}, K: class K { static n = globalThis.tries; }, o: { at: globalThis.tries }, list: [globalThis.tries], re: /x/g, arrow: () => counter, bump: () => ++counter }); let counter = globalThis.tries * 10; const stamp = "try " + globalThis.tries;\nif (globalThis.tries < 3) throw new Error("it throws at " + stamp);\n'
SEEN = 'const s = globalThis.seen; console.log(s.length, s[0].k === s[1].k, s[1].k === s[2].k, s[0].f === s[1].f, s[0].K === s[2].K, s.map(x => x.K.n).join(), s.map(x => x.o.at).join(), s[0].o === s[1].o, s[0].list === s[2].list, s[0].re === s[1].re, s.map(x => x.arrow()).join(), s[0].bump(), s[2].bump(), s.map(x => x.arrow()).join()); const o = {}; for (const x of s) o[x.k] = 1; console.log(Object.getOwnPropertySymbols(o).length);\n'
cases["commonjs-threw-twice-and-is-required-again"] = {"lib.cjs": THREW + 'module.exports = stamp;\n', "main.cjs": 'for (let i = 0; i < 3; i++) { try { console.log(require("./lib.cjs")); } catch (e) { console.log(e.message); } }\n' + SEEN}
cases["es-threw-twice-and-is-imported-again"] = {"lib.mjs": THREW + 'export default stamp;\n', "main.mjs": 'for (let i = 0; i < 3; i++) { try { console.log((await import("./lib.mjs")).default); } catch (e) { console.log(e.message); } }\n' + SEEN.replace("s[1]", "(s[1] ?? s[0])").replace("s[2]", "(s[2] ?? s[0])")}
# a query that is COMPUTED at run time (the way to load a file anew: config reloaders, hot reload): plain evaluates the file once a query.
STATE = 'globalThis.loads = (globalThis.loads ?? 0) + 1; let n = 0; const k = Symbol("k"); class K { static at = globalThis.loads; } function f() { return n; }\nconsole.log("the library is evaluated", globalThis.loads);\n'
USE = 'a.bump(); a.bump(); b.bump(); console.log(a === b, b === c, a.read(), b.read(), c.read(), a.k === b.k, a.K === b.K, [a, b, c].map(x => x.K.at).join(), a.f === c.f, globalThis.loads);\n'
cases["a-computed-query-es"] = {"lib.mjs": STATE + 'export default { bump: () => ++n, read: () => n, k, K, f };\n', "main.mjs": 'const q = i => "?v=" + [i][0];\nconst a = (await import("./lib.mjs")).default, b = (await import("./lib.mjs" + q(1))).default, c = (await import("./lib.mjs" + q(2))).default, again = (await import("./lib.mjs" + q(1))).default;\n' + USE + 'console.log(again === b);\n'}
cases["a-computed-query-typescript"] = {"lib.ts": 'declare const console: { log(...v: unknown[]): void };\nconst g = globalThis as any; g.loads = (g.loads ?? 0) + 1; let n: number = 0; const k: symbol = Symbol("k"); class K { static at: number = g.loads; } function f(): number { return n; }\nconsole.log("the library is evaluated", g.loads);\nexport default { bump: (): number => ++n, read: (): number => n, k, K, f };\n', "main.ts": 'declare const console: { log(...v: unknown[]): void };\nconst q = (i: number): string => "?v=" + [i][0];\nconst a = (await import("./lib.ts")).default, b: typeof a = (await import("./lib.ts" + q(1))).default, c: typeof a = (await import("./lib.ts" + q(2))).default, again: typeof a = (await import("./lib.ts" + q(1))).default;\n' + USE.replace("globalThis.loads", "(globalThis as any).loads") + 'console.log(again === b);\n'}
cases["a-computed-query-required"] = {"lib.cjs": STATE + 'module.exports = { bump: () => ++n, read: () => n, k, K, f };\n', "main.cjs": 'const q = i => "?v=" + [i][0]; const t = p => { try { return require(p); } catch (e) { return null; } };\nconst a = require("./lib.cjs"), b = t("./lib.cjs" + q(1)), c = t("./lib.cjs" + q(2));\nif (!b || !c) console.log("a query cannot be required"); else { ' + USE.strip().replace("\\n", "") + ' }\n'}
cases["a-computed-fragment-and-an-absolute-url"] = {"lib.mjs": STATE + 'export default { bump: () => ++n, read: () => n, k, K, f };\n', "main.mjs": 'const a = (await import("./lib.mjs")).default, b = (await import(new URL("./lib.mjs", import.meta.url).href)).default, c = (await import(import.meta.dir + "/lib.mjs")).default;\n' + USE}
for name, files in cases.items():
    os.makedirs(f"{out}/{name}", exist_ok=True)
    for f, text in files.items(): open(f"{out}/{name}/{f}", "w").write(text)
print(len(cases), "cases")
